import numpy as np,json
m=json.load(open('/app/output/initial/meta.json'))
for cam in ['egoview','robot0_agentview_center','robot0_agentview_left','robot0_agentview_right']:
 d=np.load('/app/output/initial/depth_'+cam+'.npy');print(cam,d.shape, 'minmax',d[d>0].min(),d.max())
 if cam!='egoview':continue
 c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);
 for name,(u,v) in {'can_top':(305,196),'can_edge':(291,196),'bowl_center':(100,218),'bowl_edge':(90,195),'red_circle':(165,150),'red_edge':(165,120),'distractor':(219,170),'table':(200,205)}.items():
  for du,dv in [(0,0),(-2,0),(2,0)]:
   z=float(d[-1,v+dv,u+du]);ray=np.array([(u+du-K[0,2])/K[0,0],-(v+dv-K[1,2])/K[1,1],-1]);w=T[:3,:3]@(z*ray)+T[:3,3];print(name,du,dv,'depth',z,'xyz',np.round(w,3))
